import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from qqPlot ----
/** mulberry32, seeded so both batches are byte-identical on every reload. */
function createRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function createBatch(count: number, mean: number, deviation: number, seed: number): number[] {
  const random = createRandom(seed);
  const values: number[] = [];
  while (values.length < count) {
    const u = random() || Number.EPSILON; // Box-Muller diverges at exactly zero
    const normal = Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * random());
    values.push(Math.round((mean + deviation * normal) * 10) / 10);
  }
  return values;
}

// Unequal sizes force the quantile interpolation; batch B is shifted up and spread wider,
// so the points leave the 45-degree line instead of hugging it.
const batchA: number[] = createBatch(140, 560, 55, 20260813);
const batchB: number[] = createBatch(200, 645, 88, 76540931);

const MARGIN = { top: 24, right: 24, bottom: 44, left: 56 };

/** NIST: quantiles follow the smaller sample, and the larger one is interpolated onto them. */
function quantileAt(sorted: number[], i: number, count: number): number {
  if (sorted.length === count) return sorted[i];
  const j = (i / (count - 1)) * (sorted.length - 1);
  const j0 = Math.floor(j);
  const t = j - j0;
  return t ? sorted[j0] * (1 - t) + sorted[j0 + 1] * t : sorted[j0];
}

/** The two samples to compare: `a` runs along the horizontal axis, `b` along the vertical. */
export type Data = { a: number[]; b: number[] };

const DEMO: Data = { a: batchA, b: batchB };

export default function QQPlot({ data = DEMO, width }: { data?: Data; width: number }) {
  const height = Math.min(width, 560);
  // A square plotting area, centered, so the 45-degree reference line really reads as 45 degrees.
  const side = Math.max(0, Math.min(width - MARGIN.left - MARGIN.right, height - MARGIN.top - MARGIN.bottom));
  const originX = MARGIN.left + (width - MARGIN.left - MARGIN.right - side) / 2;

  const points = useMemo(() => {
    const a = [...data.a].sort(d3.ascending);
    const b = [...data.b].sort(d3.ascending);
    const count = Math.min(a.length, b.length);
    return d3.range(count).map((i) => ({
      x: quantileAt(a, i, count),
      y: quantileAt(b, i, count)
    }));
  }, [data]);

  const extent = useMemo(() => {
    const all = [...data.a, ...data.b];
    return [d3.min(all) ?? 0, d3.max(all) ?? 0] as [number, number];
  }, [data]);

  const x = useMemo(() => d3.scaleLinear().domain(extent).nice().range([0, side]), [extent, side]);
  const y = useMemo(() => d3.scaleLinear().domain(extent).nice().range([side, 0]), [extent, side]);

  const tickCount = Math.max(3, Math.round(side / 90));

  const xTicks: Tick[] = useMemo(
    () => x.ticks(tickCount).map((v) => ({ value: String(v), offset: x(v) })),
    [x, tickCount]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(tickCount).map((v) => ({ value: String(v), offset: y(v) })),
    [y, tickCount]
  );

  const [low, high] = x.domain();

  if (width === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Quantile-quantile plot comparing the strength distributions of two ceramic batches against a 45-degree reference line">
      <g transform={`translate(${originX},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={side} />
        <AxisBottom ticks={xTicks} height={side} width={side} />

        <g className="axis">
          {xTicks.map(({ value, offset }) => (
            <line key={value} className="grid" x1={offset} x2={offset} y1={0} y2={side} />
          ))}
        </g>

        <g className="axis">
          <text x={side} y={side + MARGIN.bottom - 6} textAnchor="end">
            Batch A strength (MPa) →
          </text>
          <text x={0} y={-8} textAnchor="start">
            ↑ Batch B strength (MPa)
          </text>
        </g>

        {/* Equality line: where the points would sit if both batches shared one distribution. */}
        <line
          x1={x(low)}
          x2={x(high)}
          y1={y(low)}
          y2={y(high)}
          stroke="var(--muted)"
          strokeWidth={1.5}
          strokeDasharray="5 4"
        />

        <g fill="none" stroke="var(--accent)" strokeWidth={1.25}>
          {points.map((p, i) => (
            <circle key={i} cx={x(p.x)} cy={y(p.y)} r={2.5} />
          ))}
        </g>
      </g>
    </svg>
  );
}
